"use client";

import { useState } from "react";
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@/components/ui/sheet";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Slider } from "@/components/ui/slider";
import { Palette, RotateCcw } from "lucide-react";
import { DashboardStyle, DEFAULT_DASHBOARD_STYLE } from "@/types/dashboard";

interface StyleCustomizerProps {
  styles: DashboardStyle;
  onStylesChange: (styles: Partial<DashboardStyle>) => void;
  onReset: () => void;
}

export function StyleCustomizer({
  styles,
  onStylesChange,
  onReset,
}: StyleCustomizerProps) {
  const [open, setOpen] = useState(false);

  const handleColorChange = (key: keyof DashboardStyle, value: string) => {
    onStylesChange({ [key]: value });
  };

  const handleBorderRadiusChange = (value: number[]) => {
    onStylesChange({ borderRadius: `${value[0]}rem` });
  };

  const handleSpacingChange = (value: number[]) => {
    onStylesChange({ spacing: `${value[0]}rem` });
  };

  const handleFontSizeChange = (value: number[]) => {
    onStylesChange({ fontSize: `${value[0]}rem` });
  };

  const handleBorderWidthChange = (value: number[]) => {
    onStylesChange({ borderWidth: `${value[0]}px` });
  };

  const getBorderRadiusValue = () => {
    const match = styles.borderRadius?.match(/(\d+\.?\d*)/);
    return match ? parseFloat(match[1]) : 0.5;
  };

  const getSpacingValue = () => {
    const match = styles.spacing?.match(/(\d+\.?\d*)/);
    return match ? parseFloat(match[1]) : 1;
  };

  const getFontSizeValue = () => {
    const match = styles.fontSize?.match(/(\d+\.?\d*)/);
    return match ? parseFloat(match[1]) : 1;
  };

  const getBorderWidthValue = () => {
    const match = styles.borderWidth?.match(/(\d+\.?\d*)/);
    return match ? parseFloat(match[1]) : 2;
  };

  return (
    <Sheet open={open} onOpenChange={setOpen}>
      <SheetTrigger asChild>
        <Button variant="outline" size="sm" className="gap-2">
          <Palette className="h-4 w-4" />
          Customize Styles
        </Button>
      </SheetTrigger>
      <SheetContent className="w-[400px] sm:w-[540px] overflow-y-auto">
        <SheetHeader>
          <SheetTitle>Dashboard Style Customization</SheetTitle>
          <SheetDescription>
            Customize the appearance of your analytics dashboard. These changes
            only affect your view.
          </SheetDescription>
        </SheetHeader>

        <div className="space-y-6 mt-6">
          {/* Card Background */}
          <div className="space-y-2">
            <Label htmlFor="cardBackground">Card Background</Label>
            <div className="flex gap-2">
              <Input
                id="cardBackground"
                type="text"
                value={styles.cardBackground || ""}
                onChange={(e) =>
                  handleColorChange("cardBackground", e.target.value)
                }
                placeholder="hsl(var(--card))"
              />
              <Input
                type="color"
                className="w-16"
                onChange={(e) =>
                  handleColorChange("cardBackground", e.target.value)
                }
              />
            </div>
          </div>

          {/* Border Color */}
          <div className="space-y-2">
            <Label htmlFor="borderColor">Border Color</Label>
            <div className="flex gap-2">
              <Input
                id="borderColor"
                type="text"
                value={styles.borderColor || ""}
                onChange={(e) =>
                  handleColorChange("borderColor", e.target.value)
                }
                placeholder="hsl(var(--border))"
              />
              <Input
                type="color"
                className="w-16"
                onChange={(e) =>
                  handleColorChange("borderColor", e.target.value)
                }
              />
            </div>
          </div>

          {/* Accent Color */}
          <div className="space-y-2">
            <Label htmlFor="accentColor">Accent Color</Label>
            <div className="flex gap-2">
              <Input
                id="accentColor"
                type="text"
                value={styles.accentColor || ""}
                onChange={(e) =>
                  handleColorChange("accentColor", e.target.value)
                }
                placeholder="hsl(var(--primary))"
              />
              <Input
                type="color"
                className="w-16"
                onChange={(e) =>
                  handleColorChange("accentColor", e.target.value)
                }
              />
            </div>
          </div>

          {/* Border Radius */}
          <div className="space-y-2">
            <Label>Border Radius: {getBorderRadiusValue().toFixed(2)}rem</Label>
            <Slider
              value={[getBorderRadiusValue()]}
              onValueChange={handleBorderRadiusChange}
              min={0}
              max={2}
              step={0.1}
              className="w-full"
            />
          </div>

          {/* Border Width */}
          <div className="space-y-2">
            <Label>Border Width: {getBorderWidthValue()}px</Label>
            <Slider
              value={[getBorderWidthValue()]}
              onValueChange={handleBorderWidthChange}
              min={0}
              max={8}
              step={1}
              className="w-full"
            />
          </div>

          {/* Spacing */}
          <div className="space-y-2">
            <Label>Card Spacing: {getSpacingValue().toFixed(2)}rem</Label>
            <Slider
              value={[getSpacingValue()]}
              onValueChange={handleSpacingChange}
              min={0.25}
              max={3}
              step={0.25}
              className="w-full"
            />
          </div>

          {/* Font Size */}
          <div className="space-y-2">
            <Label>Font Size: {getFontSizeValue().toFixed(2)}rem</Label>
            <Slider
              value={[getFontSizeValue()]}
              onValueChange={handleFontSizeChange}
              min={0.75}
              max={1.5}
              step={0.05}
              className="w-full"
            />
          </div>

          {/* Reset Button */}
          <Button
            variant="outline"
            className="w-full gap-2"
            onClick={() => {
              onReset();
              setOpen(false);
            }}
          >
            <RotateCcw className="h-4 w-4" />
            Reset to Default
          </Button>
        </div>
      </SheetContent>
    </Sheet>
  );
}
